def svg_icon(name: str, size: int = 18, cls: str = "md-svg-icon", fill_current: bool = False) -> str:
    """Return an inline SVG element for the given icon name."""
    inner = ICONS_PATHS.get(name, ICONS_PATHS["grid"])
    fill_attr = "currentColor" if fill_current else "none"
    cls_attr = f' class="{cls}"' if cls else ""
    return (
        f'<svg{cls_attr} width="{size}" height="{size}" viewBox="0 0 24 24" '
        f'fill="{fill_attr}" stroke="currentColor" stroke-width="1.85" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{inner}</svg>'
    )
